* {
    font-family: "Futura", "Futura-PDF", "Trebuchet MS", "Arial", sans-serif !important;
}



/* ===== TITLE BOX ===== */
.title-box {
    border: 2px solid #000;
    padding: 10px;
    margin-bottom: 15px;
    text-align: center;
}

.title-box h2 {
    margin: 0 0 8px 0;
}

.title-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
}

.title-table td {
    border: 1px solid #000;
    padding: 6px;
}

.print-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    font-size: 11px;
}

.print-table th,
.print-table td {
    border: 1px solid #000;
    padding: 6px;
}

.print-table th {
    background-color: #f2f2f2;
}

.right {
    text-align: right;
}

.total-line {
    text-align: right;
    font-size: 12px;
    margin-top: 6px;
    margin-bottom: 15px;
    font-weight: bold;
}

h3 {
    margin-top: 20px;
    margin-bottom: 6px;
}

.terms {
    font-size: 11px;
    border: 0px solid #000;
    padding: 10px;
}

.title-table td {
    text-align: center;
}
.text-center {
    text-align: center;
}
.exclusions-list {
    margin-left: 40px;          
    font-size: 15.5px;          
    line-height: 1.6;           
}

.exclusions-list li {
    margin-bottom: 10px;        
    padding-left: 6px;          
}
.delivery-list,
.payment-list {
    margin-left: 40px;
    font-size: 13.5px;
    line-height: 1.6;
}

.delivery-list li,
.payment-list li {
    margin-bottom: 10px;
    padding-left: 6px;
}

.note-text {
    margin-left: 25px;
    font-size: 13.5px;
    line-height: 1.6;
}
.notes-list,
.warranty-list {
    margin-left: 40px;
    font-size: 13.5px;
    line-height: 1.6;
}

.notes-list li,
.warranty-list li {
    margin-bottom: 10px;
    padding-left: 6px;
}

