/* -------- Signature Stamp Layout -------- */

.signature-block {
    position: relative;
    margin-top: 40px;
    min-height: 140px;   /* space for stamp */
    padding-left: 64px;
}

.signature-content {
    position: relative;
    z-index: 1;
}

.stamp-wrapper {
    position: absolute;
    top: 10px;      /* adjust vertical position */
    left: 120px;    /* adjust horizontal position */
    z-index: 2;
}

.signature-stamp {
    width: 215px;   /* make stamp big */
    height: auto;
    opacity: 0.9;
    margin-left: -50px;
}

.scope-block {
    page-break-inside: avoid;
}

.scope-block h4 {
    page-break-after: avoid;
}
.notes-list {
    list-style: none;
    margin-left: 60px;     /* SAME AS PAYMENT & WARRANTY */
    padding-left: 0;
    font-size: 13.5px;
    line-height: 1.6;
}

.notes-list li {
    position: relative;
    padding-left: 18px;
    margin-bottom: 10px;
    text-align: left;
}

.notes-list li::before {
    content: "\2022";     /* PDF-safe bullet */
    position: absolute;
    left: 0;
    top: 0;
    font-size: 16px;
    line-height: 1;
}
